 for(let r of previous){let a=assess(r.weights,normalizedCandidateConfig(c),false),v=a.cycles.filter(x=>x.complete&&Number.isFinite(x.change));r.score=a.score;r.change_cv=a.change_cv;r.baseline_noise_mean=v.length?mean(v.map(x=>x.baseline_sd)):null;r.mean_signal_to_sd=v.length?mean(v.map(x=>x.signal_to_sd)):null;r.mean_change=v.length?mean(v.map(x=>x.change)):null;r.change_sd=v.length>=2?sd(v.map(x=>x.change)):null;r.baseline_drift=v.length?mean(v.map(x=>x.baseline_drift).filter(Number.isFinite)):null;r.noise_floor=a.noise_floor;r.selection_reason=a.selection_reason||'구간 자료 부족';r.cycle_results=a.cycles;r.analysis_metric=a.analysis_metric;}
 let base=[...names,'br_difference','br_contrast','h_cos','v_contrast'].map(k=>researchCandidate(k,c));
 if(totalSelected(weights)){let a=assess(weights,normalizedCandidateConfig(c),false);base.push({...candidateMetrics(a),name:'사용자 정의 · '+combinationName(weights),metric_code:'user_combination',weights:weights.slice(),analysis_metric:a.analysis_metric,score:a.score,change_cv:a.change_cv,complete_cycles:a.complete_cycles,baseline_noise_mean:a.cycles.length?mean(a.cycles.map(x=>x.baseline_sd).filter(Number.isFinite)):null,noise_floor:a.noise_floor,selection_reason:a.selection_reason,cycle_results:a.cycles});}
