function researchChart(canvas,series,{title='',xLabel='Time (s)',yLabel='',phases=[],boundaries=false,light=false,range=null,subtitle='',domain=null}={}){
 let ctx=canvas.getContext('2d'),W=canvas.width,H=canvas.height,dark=!light&&document.documentElement.dataset.theme==='dark',fg=dark?'#c9c5d5':'#315367',bg=dark?'#161b31':'#ffffff';ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);let p=series.flatMap(s=>s.points).filter(p=>Number.isFinite(p[0])&&Number.isFinite(p[1]));ctx.fillStyle=fg;ctx.font='bold 15px DashboardRound, sans-serif';ctx.fillText(title,72,23);ctx.font='11px DashboardRound, sans-serif';ctx.fillText(subtitle.slice(0,125),72,42);if(!p.length){ctx.fillText('계산할 데이터가 없습니다.',72,90);return;}
 let times=rows.map(r=>r.global_time_s).filter(Number.isFinite),xmin=domain?domain[0]:times.length?Math.min(...times):Math.min(...p.map(x=>x[0])),xmax=domain?domain[1]:times.length?Math.max(...times):Math.max(...p.map(x=>x[0]));if(xmin===xmax)xmax=xmin+1;let ys=p.map(x=>x[1]),ymin=range?range[0]:Math.min(...ys),ymax=range?range[1]:Math.max(...ys),pad=range?0:(ymax-ymin||1)*.08;ymin-=pad;ymax+=pad;if(ymax===ymin)ymax=ymin+1;let legendCols=Math.max(1,Math.floor((W-96)/280)),legendRows=Math.max(1,Math.ceil(series.length/legendCols)),L=72,R=W-24,T=78,B=H-64-(legendRows-1)*18,X=x=>L+(x-xmin)/(xmax-xmin)*(R-L),Y=y=>B-(y-ymin)/(ymax-ymin)*(B-T);
 ctx.save();ctx.beginPath();ctx.rect(L,T,R-L,B-T);ctx.clip();for(let [a,b,color]of phases){ctx.fillStyle=dark?(color==='#FBEFE5'?'#9c61551a':'#648aab1a'):color;ctx.fillRect(X(a),T,X(b)-X(a),B-T);}ctx.restore();
 for(let i=0;i<=5;i++){let y=ymin+(ymax-ymin)*i/5,x=xmin+(xmax-xmin)*i/5;ctx.strokeStyle=dark?'#34384e':'#e1e8eb';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(L,Y(y));ctx.lineTo(R,Y(y));ctx.stroke();ctx.fillStyle=fg;ctx.fillText(y.toFixed(Math.abs(ymax-ymin)<2?3:1),9,Y(y)+4);ctx.fillText(x.toFixed(0),X(x)-12,B+18);}
 if(boundaries){ctx.save();ctx.setLineDash([4,4]);ctx.strokeStyle=dark?'#71859b':'#92a7b7';let unique=new Set();for(let i=1;i<rows.length;i++)if(rows[i].video!==rows[i-1].video){let t=rows[i].global_time_s;if(unique.has(t))continue;unique.add(t);ctx.beginPath();ctx.moveTo(X(t),T);ctx.lineTo(X(t),B);ctx.stroke();}ctx.restore();}
 let gap=researchObservedInterval()*1.8;ctx.save();ctx.beginPath();ctx.rect(L,T,R-L,B-T);ctx.clip();series.forEach((s,k)=>{ctx.strokeStyle=s.color||['#078789','#d47951','#597cd1'][k%3];ctx.lineWidth=1.8;ctx.beginPath();let begun=false,previous=null;for(let p of s.points){if(!Number.isFinite(p[1])||!Number.isFinite(p[0])){begun=false;previous=null;continue;}if(!begun||previous!==null&&p[0]-previous>gap)ctx.moveTo(X(p[0]),Y(p[1]));else ctx.lineTo(X(p[0]),Y(p[1]));begun=true;previous=p[0];}ctx.stroke();});ctx.restore();
 ctx.fillStyle=fg;ctx.font='12px DashboardRound, sans-serif';ctx.fillText(yLabel,9,65);ctx.fillText(xLabel,(L+R)/2-25,H-12);series.forEach((s,i)=>{ctx.fillStyle=s.color||'#078789';ctx.fillText(s.label||'',L+(i%legendCols)*(R-L)/legendCols,H-33-(legendRows-1)*18+Math.floor(i/legendCols)*18);});
}
