buildReportPages=function(a,candidates,q,cal,info,photos){let pages=researchOriginalReport(a,candidates,q,cal,info,photos),c=config(),v=researchVAssessment(c,false),records=researchCycleRecords(v);if(records.length){let body='<div class="rFlow"><h3>논문식 V Response와 Brightness 변화량</h3><p>'+rEsc(researchModeLabel())+' · '+rEsc(c.timing_source)+' · 평균 구간 '+c.baseline_window+'초.</p><p>픽셀별 max(R,G,B)/255를 평균하여 Brightness(%)로 표시합니다. ΔBrightness = Vg−Va (%p). Response_V = (Va/Vg−1)×100 (%). 기준 대비 표시와 무관하게 비율은 절대 V로 계산합니다.</p>'+rTable(['회차','ppm','Va(%)','Vg(%)','Vrec(%)','Δ(%p)','Response_V(%)'],records.map(r=>[r.Cycle,r.Concentration_ppm??'미기록',rText(r.Va_percent),rText(r.Vg_percent),rText(r.Vrec_percent),rText(r.Delta_Brightness_pct_point),rText(r.Response_V_percent)]))+'<h3>V 기준 시간 및 회복</h3>'+rTable(['회차','노출 종료값 기준 t90(s)','회복 t'+c.recovery_percent+'(s)','회복률(%)','계산 상태'],records.map(r=>[r.Cycle,rTime(r.Response_t90_s),rTime(r.Recovery_time_s),rText(r.Recovery_rate_percent),r.Result_status]))+'<p>연속 3표본을 확인하며 제외값·시간 공백을 건너뛰지 않습니다. 평형값 검증이 아닌 노출 종료 평균값을 기준으로 합니다. 도달하지 않은 시간은 미확인으로 남깁니다. 회복률은 제한하지 않습니다.</p><p>논문: Shin et al., Sensors and Actuators B (2020), DOI 10.1016/j.snb.2020.128612, V 변환식 및 Response 식. ROI 평균·30/100초 대표 구간·t90/t80·노이즈 하한은 본 프로그램의 분석 정의입니다.</p></div>';pages.push(rPage('부록 - Brightness 및 논문식 V 분석',body));}return pages;};
