async function researchImportSettings(e){try{if(busy)throw Error('추출 종료 후 설정을 불러오세요.');let file=e.target.files?.[0];if(!file)return;let d=JSON.parse(await file.text()),c=d.analysis||d.settings?.analysis;if(!c||!Array.isArray(c.cycle_plan))throw Error('analysis.cycle_plan이 있는 프로그램 설정 JSON을 선택하세요.');planRanges(c);let numeric=['fps','edge','baseline_window','recovery_percent'];for(let k of numeric)if(!Number.isFinite(c[k]))throw Error('설정 숫자 누락: '+k);if(c.sensor&&(!Array.isArray(c.sensor)||c.sensor.some(p=>!Array.isArray(p)||p.length!==2||p.some(x=>!Number.isFinite(x)||x<0||x>1))))throw Error('센서 ROI 좌표를 확인하세요.');if(c.white&&(!Array.isArray(c.white)||c.white.length!==4||c.white.some(x=>!Number.isFinite(x)||x<0||x>1)))throw Error('White ROI 좌표를 확인하세요.');let v=c.native_signal?nativeValidateView(c.native_signal):null;let cal=d.research_revision?.calibration||c.white_baseline;if(cal&&(!researchModes[cal.mode]||cal.white_baseline&&(!Array.isArray(cal.white_baseline)||cal.white_baseline.length!==3||cal.white_baseline.some(x=>!Number.isFinite(x)||x<5))))throw Error('보정 설정을 확인하세요.');
 for(let k of numeric)$(k).value=c[k];cyclePlan=c.cycle_plan.map(x=>({...x}));$('firstInjection').value=c.first_injection_auto?'':cyclePlan[0].gas_on_s;estimatedFirst=c.first_injection_auto&&Number.isFinite(c.first_injection_estimated_s)?c.first_injection_estimated_s:null;timingInference=c.timing_inference||null;timingUnresolved=!!c.first_injection_auto&&!Number.isFinite(estimatedFirst);$('confirmed').checked=!!c.confirmed&&!c.first_injection_auto;$('timingRecord').value=$('confirmed').checked?'confirmed':'assumed';if(c.sensor)sensor=c.sensor.map(p=>p.slice());if(c.white)white=c.white.slice();if(cal){researchCalibration={...researchCalibration,...cal};$('relativeStart').value=cal.baseline_start_s??0;$('relativeEnd').value=cal.baseline_end_s??30;$('calibrationMode').value=cal.mode;}if(Array.isArray(c.weights)&&c.weights.length===6&&c.weights.every(Number.isFinite))weights=c.weights.slice();if(v)nativeRestoreView(v);else sliders();let records=d.research_revision?.quality_reviews||d.quality_review?.records||[];for(let r of rows){let review=records.find(x=>x.global_time_s===r.global_time_s&&x.video===(r.video||r.video_id||''));if(review){r.quality_review_status=review.status;r.quality_review_reason=review.reason;r.quality_reviewed_at=review.reviewed_at;}}
 renderPlan();schedule();drawFrame();nativeInvalidateReport();if(rows.length&&totalSelected(weights))await evaluate();researchRefreshCalibration();syncNativeControls();status('저장한 농도·시각·ROI·분석 설정을 복원했습니다. 영상 이름/순서는 JSON 기록과 선택 파일을 확인하세요.');}catch(e){status(e.message,true);}}
