const researchBaseInferTiming=inferTimingFromColors;
inferTimingFromColors=function(data,plan){let mapped=data.map(r=>{let result={...r};for(let k of ['R','G','B','H_deg','S','V','H_coherence'])result['cal_'+k]=researchValue(r,k);let R=result.cal_R,B=result.cal_B;result.cal_BR=Number.isFinite(R)&&Number.isFinite(B)&&B+R>1e-6?(B-R)/(B+R):null;return result;});return researchBaseInferTiming(mapped,plan);};
const researchModeSetter=researchSetMode;
