const researchReportWithV=buildReportPages;
buildReportPages=function(a,candidates,q,cal,info,photos){let pages=researchReportWithV(a,candidates,q,cal,info,photos),vpage=pages.find(p=>p.title==='부록 - Brightness 및 논문식 V 분석');if(vpage&&info.quality&&q.notes.length){let note='<p>'+rEsc(q.notes.join(' / '))+'</p>';for(let p of pages)if(p.title==='부록 - 지표 비교 및 실험 기록')p.body=p.body.replace(note,'');let end=vpage.body.lastIndexOf('</div>');vpage.body=vpage.body.slice(0,end)+'<h3>품질 검사 참고</h3>'+note+vpage.body.slice(end);}return pages;};

